  ".closing{padding-top:24px}.cbox{text-align:center;padding:64px 28px;border-radius:24px;background:var(--surface);border:1px solid var(--border);position:relative;overflow:hidden}.cbox:before{content:'';position:absolute;inset:-50% 15% auto;height:320px;background:radial-gradient(closest-side,var(--g1),transparent),radial-gradient(closest-side at 70% 50%,var(--g2),transparent);opacity:.22;filter:blur(40px)}.cbox *{position:relative}.cbox h2{font-size:clamp(28px,3.6vw,42px);font-weight:800;letter-spacing:-.03em;margin-bottom:10px}.cbox p{color:var(--muted);margin-bottom:24px}"+
  "@media(max-width:900px){.body .wrap{grid-template-columns:1fr;gap:36px}.side{position:static}.facts{gap:24px}}";
